-- MySQL 8.4: shared capabilities for the compact model. Empty schema only.

CREATE TABLE runtime_state (
    namespace VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    owner_id BIGINT NOT NULL,
    scope_key VARCHAR(160) COLLATE utf8mb4_bin NOT NULL DEFAULT '',
    session_id VARCHAR(160) COLLATE utf8mb4_bin NULL,
    state_key VARCHAR(160) COLLATE utf8mb4_bin NULL,
    revision BIGINT NOT NULL DEFAULT 0,
    state_code VARCHAR(32) COLLATE utf8mb4_bin NULL,
    current_ref VARCHAR(180) COLLATE utf8mb4_bin NULL,
    counter_value BIGINT NULL,
    provider VARCHAR(24) COLLATE utf8mb4_bin NULL,
    credential_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
    actor_user_id BIGINT NULL,
    request_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    window_started_at DATETIME(6) NULL,
    window_ends_at DATETIME(6) NULL,
    payload_version SMALLINT NOT NULL DEFAULT 1,
    payload_json LONGTEXT NULL,
    created_at DATETIME(6) NULL,
    updated_at DATETIME(6) NULL DEFAULT (UTC_TIMESTAMP(6)),
    PRIMARY KEY (namespace,owner_id,scope_key),
    UNIQUE KEY uk_runtime_sdk_slot (namespace,owner_id,session_id,state_key),
    CONSTRAINT ck_runtime_owner CHECK (owner_id>=0),
    CONSTRAINT ck_runtime_revision CHECK (revision>=0),
    CONSTRAINT ck_runtime_counter CHECK (counter_value IS NULL OR counter_value>=0),
    CONSTRAINT ck_runtime_updated CHECK (((namespace='RESEARCH_EXPORT_LIMIT' OR updated_at IS NOT NULL OR (namespace IN ('CONTEXT_HEAD','CONTEXT_BOOTSTRAP') AND created_at IS NULL AND payload_json IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=CASE namespace WHEN 'CONTEXT_HEAD' THEN 'agent_context_head' ELSE 'agent_context_bootstrap' END) OR (namespace='DETECTION_CREATION_OWNER' AND created_at IS NULL AND payload_version=1 AND payload_json IS NOT NULL AND JSON_LENGTH(payload_json)=1 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_creation_owner')) OR (created_at IS NULL AND payload_json IS NOT NULL AND payload_version=1 AND ((namespace='DETECTION_IDENTITY_CONTROL' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_control') OR (namespace='DETECTION_IDENTITY_SOURCE_CONTROL' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_source_control') OR (namespace='DETECTION_IDENTITY_BINDING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_binding')))) OR (namespace IN ('RESEARCH_STORAGE','SKILL_DOWNLOAD') AND owner_id>0 AND scope_key='' AND revision=0 AND payload_json IS NULL AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL)),
    CONSTRAINT ck_runtime_payload_version CHECK (payload_version>0),
    CONSTRAINT ck_runtime_payload CHECK (payload_json IS NULL OR (JSON_VALID(payload_json) AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT')),
    CONSTRAINT ck_runtime_sdk CHECK ((namespace='SDK_CHECKPOINT' AND owner_id>0 AND session_id IS NOT NULL AND state_key IS NOT NULL AND CHAR_LENGTH(state_key)<=128 AND CHAR_LENGTH(scope_key)=64 AND revision>0 AND payload_version=1 AND payload_json IS NOT NULL) OR (namespace IN ('CONTEXT_HEAD','CONTEXT_BOOTSTRAP') AND owner_id>0 AND session_id IS NOT NULL AND state_key IS NOT NULL AND CHAR_LENGTH(scope_key)=64 AND payload_version=1 AND payload_json IS NOT NULL) OR (namespace NOT IN ('SDK_CHECKPOINT','CONTEXT_HEAD','CONTEXT_BOOTSTRAP') AND session_id IS NULL AND state_key IS NULL)),
    CONSTRAINT ck_runtime_model_control CHECK (namespace<>'MODEL_CONFIG_CONTROL' OR (owner_id=0 AND scope_key='GLOBAL' AND state_code IS NOT NULL AND state_code='READY' AND counter_value IS NOT NULL AND current_ref IS NOT NULL AND current_ref REGEXP '^(0|[1-9][0-9]{0,18})$' AND CAST(current_ref AS DECIMAL(20,0))<=counter_value AND payload_json IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL)),
    CONSTRAINT ck_runtime_key_revocation CHECK ((namespace='MODEL_KEY_REVOCATION' AND owner_id=0 AND state_code IS NOT NULL AND state_code='REVOKED' AND provider IS NOT NULL AND provider IN ('dashscope','deepseek','openai') AND credential_sha256 IS NOT NULL AND credential_sha256 REGEXP '^[a-f0-9]{64}$' AND scope_key=CONCAT(provider,':',credential_sha256) AND actor_user_id IS NOT NULL AND actor_user_id>0 AND request_id IS NOT NULL AND CHAR_LENGTH(request_id)>0 AND counter_value IS NOT NULL AND counter_value IN (0,1) AND created_at IS NOT NULL AND current_ref IS NULL AND payload_json IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL) OR (namespace<>'MODEL_KEY_REVOCATION' AND provider IS NULL AND credential_sha256 IS NULL AND actor_user_id IS NULL AND request_id IS NULL)),
    CONSTRAINT ck_runtime_research_export_limit CHECK (namespace<>'RESEARCH_EXPORT_LIMIT' OR (owner_id>0 AND scope_key='' AND revision=0 AND counter_value IS NOT NULL AND window_ends_at IS NOT NULL AND window_started_at IS NULL AND state_code IS NULL AND current_ref IS NULL AND payload_json IS NULL AND created_at IS NULL AND updated_at IS NULL)),
    CONSTRAINT ck_runtime_memory_preference CHECK (namespace<>'MEMORY_PREFERENCE' OR (owner_id>0 AND scope_key='' AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL AND created_at IS NULL AND payload_version=1 AND payload_json IS NOT NULL AND JSON_LENGTH(payload_json)=2 AND JSON_EXTRACT(payload_json,'$.readEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.readEnabled'))='BOOLEAN' AND JSON_EXTRACT(payload_json,'$.saveEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.saveEnabled'))='BOOLEAN')),
    KEY ix_runtime_state (namespace,state_code,owner_id),
 CONSTRAINT ck_runtime_context_head CHECK (namespace<>'CONTEXT_HEAD' OR (payload_version=1 AND JSON_LENGTH(payload_json)=1 AND JSON_CONTAINS_PATH(payload_json,'all','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))='agent_context_head') AND state_code IS NULL AND counter_value IS NULL)),
 CONSTRAINT ck_runtime_context_bootstrap CHECK (namespace<>'CONTEXT_BOOTSTRAP' OR (payload_version=1 AND JSON_LENGTH(payload_json)=4 AND JSON_CONTAINS_PATH(payload_json,'all','$.agentScope','$.initialState','$.initialSha256','$.legacySource')=1 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.agentScope'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.agentScope')))<=160 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.initialState'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.initialSha256')) REGEXP '^[a-fA-F0-9]{64}$' AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))='agent_context_bootstrap') AND counter_value IS NOT NULL AND state_code IN ('RESERVED','INITIALIZED'))),
 CONSTRAINT ck_runtime_mcp_retention CHECK (namespace<>'MCP_RETENTION_CONTROL' OR (owner_id=0 AND scope_key REGEXP '^-?[0-9]{1,3}$' AND CAST(scope_key AS SIGNED) BETWEEN -128 AND 127 AND state_code IS NOT NULL AND state_code IN ('COLLECTING','ACTIVE') AND payload_json IS NULL AND current_ref IS NULL AND counter_value IS NULL)),
    CONSTRAINT ck_detection_creation_owner CHECK (namespace<>'DETECTION_CREATION_OWNER' OR (
   owner_id>0 AND scope_key='' AND revision=0 AND session_id IS NULL AND state_key IS NULL
   AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL
   AND ((payload_json IS NULL AND created_at IS NOT NULL AND updated_at IS NOT NULL)
     OR (payload_version=1 AND JSON_LENGTH(payload_json)=1
       AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING'
       AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_creation_owner'
       AND created_at IS NULL AND updated_at IS NULL))))
 ,
 -- BEGIN GENERATED IDENTITY
 identity_task_id VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN namespace IN ('DETECTION_IDENTITY_CONTROL','DETECTION_IDENTITY_SOURCE_CONTROL','DETECTION_IDENTITY_BINDING') THEN CASE WHEN JSON_TYPE(JSON_EXTRACT(payload_json,'$.taskId'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.taskId')) END END) VIRTUAL,
 identity_role VARCHAR(24) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN namespace IN ('DETECTION_IDENTITY_CONTROL','DETECTION_IDENTITY_SOURCE_CONTROL','DETECTION_IDENTITY_BINDING') THEN CASE WHEN JSON_TYPE(JSON_EXTRACT(payload_json,'$.identityRole'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.identityRole')) END END) VIRTUAL,
 identity_head_event_ref VARCHAR(180) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN namespace='DETECTION_IDENTITY_BINDING' THEN current_ref END) VIRTUAL,
 UNIQUE KEY uk_identity_binding (namespace,identity_task_id,identity_role),
 UNIQUE KEY uk_identity_head_event (namespace,identity_head_event_ref),
 CONSTRAINT ck_id_runtime_identity_control CHECK (namespace<>'DETECTION_IDENTITY_CONTROL' OR COALESCE((payload_version=1 AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT' AND JSON_LENGTH(payload_json)=3 AND JSON_CONTAINS_PATH(payload_json,'all','$.controlId','$.activationRevision','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.controlId'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.controlId')) AS DECIMAL(20,0)) BETWEEN -2147483648 AND 2147483647) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.activationRevision')) AS DECIMAL(20,0)) BETWEEN -9223372036854775808 AND 9223372036854775807)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource')))<=64 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_control'))),0)=1),
 CONSTRAINT ck_id_runtime_identity_source_control CHECK (namespace<>'DETECTION_IDENTITY_SOURCE_CONTROL' OR COALESCE((payload_version=1 AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT' AND JSON_LENGTH(payload_json)=3 AND JSON_CONTAINS_PATH(payload_json,'all','$.controlId','$.activationRevision','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.controlId'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.controlId')) AS DECIMAL(20,0)) BETWEEN -2147483648 AND 2147483647) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.activationRevision')) AS DECIMAL(20,0)) BETWEEN -9223372036854775808 AND 9223372036854775807)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource')))<=64 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_source_control'))),0)=1),
 CONSTRAINT ck_id_runtime_identity_binding CHECK (namespace<>'DETECTION_IDENTITY_BINDING' OR COALESCE((payload_version=1 AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT' AND JSON_LENGTH(payload_json)=6 AND JSON_CONTAINS_PATH(payload_json,'all','$.taskId','$.identityRole','$.eventSha256','$.legacyId','$.legacyEventId','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.taskId'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.taskId')))<=128) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.identityRole'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.identityRole')))<=24) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.eventSha256'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.eventSha256')))<=64) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyId'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyId'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyId')) REGEXP '^(0|[1-9][0-9]{0,19})$' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyId')) AS DECIMAL(20,0))<=18446744073709551615)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyEventId'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyEventId'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyEventId')) REGEXP '^(0|[1-9][0-9]{0,19})$' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyEventId')) AS DECIMAL(20,0))<=18446744073709551615)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource')))<=64 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_binding'))),0)=1)
 -- END GENERATED IDENTITY
 ,
 -- BEGIN GENERATED SUPPORT
 CONSTRAINT ck_runtime_fingerprint CHECK (namespace<>'DETECTION_FINGERPRINT' OR COALESCE((namespace='DETECTION_FINGERPRINT' AND owner_id=0 AND scope_key REGEXP '^[a-f0-9]{64}$' AND payload_version=1 AND payload_json IS NOT NULL AND COALESCE(JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["originalId","sourceOwnerKey"],"properties":{"originalId":{"type":"integer","minimum":1,"maximum":9223372036854775807},"sourceOwnerKey":{"type":["string","null"],"maxLength":64}}}',payload_json),0)=1 AND revision<=2147483647 AND state_code IS NOT NULL AND CHAR_LENGTH(state_code)<=32 AND (current_ref IS NULL OR CHAR_LENGTH(current_ref)<=64)),0)=1),
 CONSTRAINT ck_runtime_digest_control CHECK (namespace<>'DIGEST_CONTROL' OR (owner_id=0 AND scope_key='1' AND revision=0 AND payload_json IS NULL AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL AND created_at IS NULL))
 -- END GENERATED SUPPORT
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE workflow_instance (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    workflow_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    kind VARCHAR(48) COLLATE utf8mb4_bin NOT NULL,
    idempotency_scope VARCHAR(160) COLLATE utf8mb4_bin NOT NULL,
    request_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL,
    request_sha256 CHAR(64) COLLATE utf8mb4_bin NOT NULL,
    owner_user_id BIGINT NOT NULL,
    actor_user_id BIGINT NULL,
    parent_workflow_id BIGINT UNSIGNED NULL,
    resource_type VARCHAR(32) COLLATE utf8mb4_bin NULL,
    resource_id VARCHAR(180) COLLATE utf8mb4_bin NULL,
    resource_revision BIGINT NULL,
    requested_tokens BIGINT NULL,
    decider_user_id BIGINT NULL,
    session_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    run_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    chat_action_session_id VARCHAR(64) COLLATE utf8mb4_unicode_ci NULL,
    confirmation_recorded_at DATETIME(6) NULL,
    status VARCHAR(40) COLLATE utf8mb4_bin NOT NULL,
    revision BIGINT NOT NULL DEFAULT 0,
    fence BIGINT NOT NULL DEFAULT 0,
    active_slot TINYINT NULL,
    claim_token VARCHAR(64) COLLATE utf8mb4_bin NULL,
    lease_expires_at DATETIME(6) NULL,
    attempts INT NOT NULL DEFAULT 0,
    effective_date DATE NULL,
    scheduled_for DATETIME(6) NULL,
    error_code VARCHAR(80) COLLATE utf8mb4_bin NULL,
    next_attempt_at DATETIME(6) NULL,
    expires_at DATETIME(6) NULL,
    execution_state VARCHAR(32) COLLATE utf8mb4_bin NULL,
    reserved_bytes BIGINT NULL,
    exit_verified BOOLEAN NULL,
    execution_deadline DATETIME(6) NULL,
    payload_version SMALLINT NOT NULL,
    payload_json LONGTEXT NOT NULL,
    result_version SMALLINT NULL,
    result_json LONGTEXT NULL,
    result_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
    created_at DATETIME(6) NULL DEFAULT (UTC_TIMESTAMP(6)),
    updated_at DATETIME(6) NULL DEFAULT (UTC_TIMESTAMP(6)),
    finished_at DATETIME(6) NULL,
    legacy_source VARCHAR(64) COLLATE utf8mb4_bin NULL,
    legacy_key VARCHAR(512) COLLATE utf8mb4_bin NULL,
    knowledge_request_id VARCHAR(128) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='KNOWLEDGE_COMMAND' THEN request_id ELSE NULL END) VIRTUAL,
    fork_result_key VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='WORKSPACE_FORK' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.resultSessionId')) ELSE NULL END) VIRTUAL,
    report_request_id VARCHAR(128) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS
        (CASE WHEN kind IN ('REPORT_COMMAND','REPORT_CONFIRMATION','REPORT_DELIVERY','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN') THEN request_id ELSE NULL END) VIRTUAL,
    report_consumed_id VARCHAR(180) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS
        (CASE WHEN kind='REPORT_CONSUMPTION' THEN resource_id ELSE NULL END) VIRTUAL,
    model_probe_id VARCHAR(160) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_JSON_PROBE' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.modelId')) ELSE NULL END) VIRTUAL,
    file_delivery_scope VARCHAR(16) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='FILE_DELIVERY' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.scope')) ELSE NULL END) VIRTUAL,
    file_delivery_domain VARCHAR(48) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='FILE_DELIVERY' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.domain')) ELSE NULL END) VIRTUAL,
    agent_action_digest VARCHAR(64) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='AGENT_ACTION' THEN request_sha256 ELSE NULL END) VIRTUAL,
    agent_action_call_id VARCHAR(160) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='AGENT_ACTION' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.callId'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.callId')) ELSE NULL END) VIRTUAL,
    agent_action_operation VARCHAR(64) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='AGENT_ACTION' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.operation')) ELSE NULL END) VIRTUAL,
    chat_action_id VARCHAR(64) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS
        (CASE WHEN kind='LEGACY_CHAT_ACTION' THEN request_id ELSE NULL END) VIRTUAL,
    model_file_storage_path VARCHAR(2048) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_FILE_UPLOAD' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.storagePath'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.storagePath')) ELSE NULL END) VIRTUAL,
    model_file_path_sha256 CHAR(64) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_FILE_UPLOAD' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.pathSha256'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.pathSha256')) ELSE NULL END) VIRTUAL,
    model_file_content_sha256 CHAR(64) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_FILE_UPLOAD' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.contentSha256'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.contentSha256')) ELSE NULL END) VIRTUAL,
    model_file_byte_size BIGINT GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_FILE_UPLOAD' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.byteSize'))='INTEGER' THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.byteSize')) AS SIGNED) ELSE NULL END) VIRTUAL,
    model_file_model_id INT GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_FILE_UPLOAD' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.modelId'))='INTEGER' THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.modelId')) AS SIGNED) ELSE NULL END) VIRTUAL,

 call_id VARCHAR(160) COLLATE utf8mb4_bin NULL,
 mcp_installation_id VARCHAR(36) COLLATE utf8mb4_bin NULL,
 mcp_prior_installation_id VARCHAR(36) COLLATE utf8mb4_bin NULL,
 mcp_owner_username VARCHAR(128) NULL,
 mcp_runtime_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
 mcp_pool_id CHAR(32) COLLATE utf8mb4_bin NULL,
 mcp_purpose VARCHAR(16) NULL,
 mcp_transport VARCHAR(32) NULL,
 mcp_image_id VARCHAR(80) COLLATE utf8mb4_bin NULL,
 mcp_exit_verified BOOLEAN NULL,
 mcp_cleanup_confirmed BOOLEAN NULL,
 mcp_worker_token VARCHAR(64) NULL,
 mcp_writer_exit_verified BOOLEAN NULL,
 mcp_retained_for_rollback BOOLEAN NULL,
 mcp_package_version VARCHAR(64) NULL,
 mcp_manifest_json JSON NULL,
 mcp_manifest_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
 mcp_cleanup_request VARCHAR(64) COLLATE utf8mb4_bin NULL,
 mcp_cleanup_expires_at DATETIME(6) NULL,
 mcp_reconcile_request VARCHAR(64) COLLATE utf8mb4_bin NULL,
 mcp_reconcile_expires_at DATETIME(6) NULL,
 mcp_writer_evidence_code VARCHAR(48) NULL,
 mcp_node_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
 mcp_controller_pid BIGINT NULL,
 mcp_controller_started VARCHAR(48) NULL,
 mcp_container_id CHAR(64) COLLATE utf8mb4_bin NULL,
 mcp_container_started VARCHAR(64) NULL,
 mcp_controller_pool_id CHAR(32) COLLATE utf8mb4_bin NULL,
 mcp_native_pool_id CHAR(32) COLLATE utf8mb4_bin NULL,
 mcp_action VARCHAR(24) NULL,
 mcp_retention_protocol INT NULL,
 mcp_source_created_at DATETIME(6) NULL,
 mcp_source_updated_at DATETIME(6) NULL,
 mcp_source_utc_offset CHAR(6) COLLATE utf8mb4_bin NULL,
 workbench_item_id VARCHAR(64) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') THEN resource_id ELSE NULL END) VIRTUAL,
 workbench_parent_item_id VARCHAR(64) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data.parentId'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.data.parentId')) ELSE NULL END) VIRTUAL,
 workbench_parent_task_id VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data.parentTaskId'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.data.parentTaskId')) ELSE NULL END) VIRTUAL,
 workbench_logical_task_id VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data.logicalTaskId'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.data.logicalTaskId')) ELSE NULL END) VIRTUAL,
 workbench_specialist VARCHAR(100) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data.specialist'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.data.specialist')) ELSE NULL END) VIRTUAL,
 workbench_role VARCHAR(24) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data.role'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.data.role')) ELSE NULL END) VIRTUAL,
 workbench_instance VARCHAR(36) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data.instance'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.data.instance')) ELSE NULL END) VIRTUAL,
 workbench_yield_ready BOOLEAN GENERATED ALWAYS AS (CASE WHEN kind IN ('WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.data.yieldReady'))='BOOLEAN' THEN JSON_EXTRACT(payload_json,'$.data.yieldReady')=TRUE ELSE NULL END) VIRTUAL,

    detection_pair_task VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS
   (CASE WHEN kind IN ('DETECTION_DISPATCH','DETECTION_WORKER') THEN resource_id ELSE NULL END) VIRTUAL,
    detection_pair_dispatch VARCHAR(64) COLLATE utf8mb4_bin GENERATED ALWAYS AS
   (CASE WHEN kind IN ('DETECTION_DISPATCH','DETECTION_WORKER') THEN run_id ELSE NULL END) VIRTUAL,
    detection_creation_task VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS
   (CASE WHEN kind='DETECTION_CREATION' THEN resource_id ELSE NULL END) VIRTUAL,
    detection_transfer_command VARCHAR(36) COLLATE utf8mb4_bin GENERATED ALWAYS AS
   (CASE WHEN kind='DETECTION_TRANSFER' THEN resource_id ELSE NULL END) VIRTUAL,
    detection_transfer_index INT GENERATED ALWAYS AS
   (CASE WHEN kind='DETECTION_TRANSFER' THEN resource_revision ELSE NULL END) VIRTUAL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_workflow_external (workflow_id),
