    KEY ix_workflow_delivery_domain (kind,file_delivery_domain,id),
    KEY ix_workflow_delivery_owner (kind,owner_user_id,id),
    KEY ix_workflow_delivery_pending (kind,status,updated_at,id),
    KEY ix_workflow_agent_action_call (kind,owner_user_id,run_id,agent_action_call_id),
    KEY ix_workflow_chat_action_session (kind,chat_action_session_id,status,created_at),
    KEY ix_workflow_model_file_model (kind,model_file_model_id,status,id),
    KEY ix_workflow_model_file_created (kind,created_at,resource_id),
    CONSTRAINT fk_workflow_parent FOREIGN KEY(parent_workflow_id) REFERENCES workflow_instance(id),
    CONSTRAINT ck_workflow_kind CHECK (kind IN ('CONVERSATION_INPUT','KNOWLEDGE_COMMAND','WORKSPACE_FORK','DIGEST_RUN','DIGEST_COMMAND','LLM_REQUEST','LLM_PROVIDER_ATTEMPT','REPORT_COMMAND','REPORT_CONFIRMATION','REPORT_DELIVERY','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN','MODEL_CONFIG_COMMAND','MODEL_JSON_PROBE','SKILL_IMPORT_COMMAND','SKILL_DOWNLOAD','SKILL_STORAGE_COMMAND','MEMORY_MUTATION','LLM_QUOTA_CHANGE','LLM_QUOTA_APPLICATION','FILE_DELIVERY','WORKSPACE_MUTATION','MODEL_FILE_UPLOAD','AGENT_ACTION','LEGACY_CHAT_ACTION','WORKBENCH_EXECUTION','WORKBENCH_CHILD','WORKBENCH_PLAN','WORKBENCH_QUESTION','WORKBENCH_TASKS','WORKBENCH_TOOL','WORKBENCH_CHECKPOINT','WORKBENCH_MODEL_SELECTION','WORKBENCH_TURN','WORKBENCH_FORK_SNAPSHOT','WORKBENCH_ARTIFACT','WORKBENCH_USAGE','WORKBENCH_CONTEXT','WORKBENCH_TOOL_TIMING','WORKBENCH_COMMAND','WORKBENCH_LOGICAL_TASK','MCP_INSTALL_JOB','MCP_EXECUTION','MCP_EXECUTION_COMMAND','MCP_INSTALLATION','MCP_LIFECYCLE_COMMAND','MCP_INSTALL_WORKER','MCP_IMAGE_COMMAND','DETECTION_CREATION','DETECTION_TRANSFER','DETECTION_TRANSFER_REVIEW','DETECTION_COMMAND','DETECTION_DISPATCH','DETECTION_WORKER','DETECTION_IDENTITY_COMMAND','DETECTION_IDENTITY_MAP_BATCH','DETECTION_IDENTITY_MAP_ITEM','DETECTION_IDENTITY_REPORT')),
    CONSTRAINT ck_workflow_owner CHECK (((owner_user_id>0 OR (kind='DETECTION_WORKER' AND owner_user_id=0 AND actor_user_id IS NULL) OR (kind='DETECTION_TRANSFER' AND owner_user_id=0 AND actor_user_id IS NULL AND legacy_source='detection_creation_object' AND legacy_key IS NOT NULL)) AND (actor_user_id IS NULL OR actor_user_id>0)) OR (owner_user_id=0 AND actor_user_id IS NULL AND legacy_key IS NOT NULL AND ((kind='DETECTION_IDENTITY_COMMAND' AND BINARY legacy_source=BINARY 'detection_identity_command') OR (kind='DETECTION_IDENTITY_MAP_BATCH' AND BINARY legacy_source=BINARY 'detection_identity_mapping_batch') OR (kind='DETECTION_IDENTITY_MAP_ITEM' AND BINARY legacy_source=BINARY 'detection_identity_mapping_item') OR (kind='DETECTION_IDENTITY_REPORT' AND BINARY legacy_source=BINARY 'detection_identity_reconciliation_report')))),
    CONSTRAINT ck_workflow_versions CHECK (revision>=0 AND fence>=0 AND attempts>=0 AND payload_version>0),
    CONSTRAINT ck_workflow_payload CHECK (JSON_VALID(payload_json)),
    CONSTRAINT ck_workflow_result CHECK ((result_json IS NULL AND result_version IS NULL AND result_sha256 IS NULL) OR (result_json IS NOT NULL AND result_version IS NOT NULL AND result_version>0 AND result_sha256 IS NOT NULL AND JSON_VALID(result_json))),
    CONSTRAINT ck_workflow_claim CHECK ((claim_token IS NULL AND lease_expires_at IS NULL) OR (claim_token IS NOT NULL AND lease_expires_at IS NOT NULL AND fence>0) OR (kind IN ('DETECTION_WORKER','DETECTION_TRANSFER') AND claim_token IS NOT NULL AND lease_expires_at IS NULL AND fence>0) OR (kind='MCP_EXECUTION' AND claim_token IS NULL AND lease_expires_at IS NOT NULL) OR (kind='DETECTION_CREATION' AND BINARY legacy_source=BINARY 'detection_creation_job' AND legacy_key IS NOT NULL AND status='CANCELLED' AND claim_token IS NULL AND lease_expires_at IS NOT NULL)),
    CONSTRAINT ck_workflow_legacy CHECK ((legacy_source IS NULL AND legacy_key IS NULL) OR (legacy_source IS NOT NULL AND legacy_key IS NOT NULL)),
    CONSTRAINT ck_workflow_created_time CHECK ((created_at IS NOT NULL OR (legacy_source IS NOT NULL AND legacy_key IS NOT NULL AND ((kind='DETECTION_TRANSFER' AND BINARY legacy_source=BINARY 'detection_creation_object') OR (kind='WORKBENCH_LOGICAL_TASK' AND BINARY legacy_source=BINARY 'agent_workbench_logical_task') OR (kind='DETECTION_COMMAND' AND BINARY legacy_source=BINARY 'detection_execution_command') OR (kind='WORKBENCH_COMMAND' AND BINARY legacy_source=BINARY 'agent_workbench_request') OR (kind='WORKSPACE_MUTATION' AND BINARY legacy_source=BINARY 'agent_workspace_request') OR (kind='WORKSPACE_FORK' AND BINARY legacy_source=BINARY 'agent_session_fork') OR (kind='LEGACY_CHAT_ACTION' AND BINARY legacy_source=BINARY 'chat_pending_action') OR (kind='REPORT_CONFIRMATION' AND BINARY legacy_source=BINARY 'detection_report_confirmation')))) OR (kind='DETECTION_IDENTITY_MAP_ITEM' AND BINARY legacy_source=BINARY 'detection_identity_mapping_item' AND legacy_key IS NOT NULL)),
    CONSTRAINT ck_workflow_updated_time CHECK (((updated_at IS NOT NULL OR (legacy_source IS NOT NULL AND legacy_key IS NOT NULL AND ((kind='WORKBENCH_LOGICAL_TASK' AND BINARY legacy_source=BINARY 'agent_workbench_logical_task') OR (kind='DETECTION_COMMAND' AND BINARY legacy_source=BINARY 'detection_execution_command') OR (kind='WORKBENCH_COMMAND' AND BINARY legacy_source=BINARY 'agent_workbench_request') OR (kind='WORKSPACE_MUTATION' AND BINARY legacy_source=BINARY 'agent_workspace_request') OR (kind='WORKSPACE_FORK' AND BINARY legacy_source=BINARY 'agent_session_fork') OR (kind='LEGACY_CHAT_ACTION' AND BINARY legacy_source=BINARY 'chat_pending_action') OR (kind='REPORT_CONFIRMATION' AND BINARY legacy_source=BINARY 'detection_report_confirmation') OR (kind='AGENT_ACTION' AND BINARY legacy_source=BINARY 'agent_pending_action')))) OR (kind='DETECTION_IDENTITY_MAP_ITEM' AND BINARY legacy_source=BINARY 'detection_identity_mapping_item' AND legacy_key IS NOT NULL)) OR (legacy_key IS NOT NULL AND ((kind='DIGEST_RUN' AND BINARY legacy_source=BINARY 'quality_digest_run') OR (kind='DIGEST_COMMAND' AND BINARY legacy_source=BINARY 'quality_digest_command')))),
    CONSTRAINT ck_workflow_confirmation_time CHECK (kind IN ('AGENT_ACTION','LEGACY_CHAT_ACTION') OR confirmation_recorded_at IS NULL),
    CONSTRAINT ck_workflow_input CHECK (kind<>'CONVERSATION_INPUT' OR (session_id IS NOT NULL AND expires_at IS NOT NULL AND payload_version=1
        AND status IN ('QUEUED','STARTED','APPLIED','COMPLETED','CANCELLED','FAILED','EXPIRED')
        AND ((status='STARTED' AND active_slot IS NOT NULL AND active_slot=1 AND claim_token IS NOT NULL) OR (status<>'STARTED' AND active_slot IS NULL)))),
    CONSTRAINT ck_workflow_knowledge_request CHECK (kind<>'KNOWLEDGE_COMMAND' OR CHAR_LENGTH(request_id)<=64),
    CONSTRAINT ck_workflow_other_slot CHECK (kind='CONVERSATION_INPUT' OR active_slot IS NULL),
    CONSTRAINT ck_workflow_receipt CHECK ((kind NOT IN ('KNOWLEDGE_COMMAND','WORKSPACE_FORK','WORKSPACE_MUTATION','DIGEST_COMMAND','REPORT_COMMAND','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN','MODEL_CONFIG_COMMAND','SKILL_IMPORT_COMMAND','LLM_QUOTA_CHANGE') OR (status='COMPLETED' AND claim_token IS NULL AND (finished_at IS NOT NULL OR (legacy_source IS NOT NULL AND legacy_key IS NOT NULL AND ((kind='WORKSPACE_MUTATION' AND BINARY legacy_source=BINARY 'agent_workspace_request') OR (kind='WORKSPACE_FORK' AND BINARY legacy_source=BINARY 'agent_session_fork')))))) OR (kind='DIGEST_COMMAND' AND status='COMPLETED' AND claim_token IS NULL AND lease_expires_at IS NULL AND legacy_key IS NOT NULL AND BINARY legacy_source=BINARY 'quality_digest_command' AND digest_legacy_row_json IS NOT NULL)),
    CONSTRAINT ck_workflow_workspace_receipt CHECK (kind NOT IN ('WORKSPACE_MUTATION','WORKSPACE_FORK') OR (idempotency_scope=CONCAT('OWNER:',owner_user_id) AND parent_workflow_id IS NULL AND run_id IS NULL AND session_id IS NULL AND expires_at IS NULL AND claim_token IS NULL AND payload_version=1 AND ((actor_user_id IS NOT NULL AND actor_user_id=owner_user_id) OR (legacy_source IS NOT NULL AND legacy_key IS NOT NULL AND ((kind='WORKSPACE_MUTATION' AND BINARY legacy_source=BINARY 'agent_workspace_request') OR (kind='WORKSPACE_FORK' AND BINARY legacy_source=BINARY 'agent_session_fork')))) AND ((created_at IS NOT NULL AND updated_at IS NOT NULL AND finished_at IS NOT NULL) OR (created_at IS NULL AND updated_at IS NULL AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_workspace_mutation CHECK (kind<>'WORKSPACE_MUTATION' OR (resource_type IS NOT NULL AND resource_type='WORKSPACE_MUTATION' AND resource_id IS NULL AND JSON_LENGTH(payload_json)=1 AND JSON_CONTAINS_PATH(payload_json,'all','$.signature')=1 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.signature'))='STRING' AND BINARY request_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.signature')) AND request_sha256 REGEXP '^[a-fA-F0-9]{64}$')),
    CONSTRAINT ck_workflow_workspace_fork CHECK (kind<>'WORKSPACE_FORK' OR (resource_type IS NOT NULL AND resource_type='SESSION' AND resource_id IS NOT NULL AND fork_result_key IS NOT NULL AND BINARY resource_id=BINARY fork_result_key AND JSON_LENGTH(payload_json)=3 AND JSON_CONTAINS_PATH(payload_json,'all','$.sourceSessionId','$.throughMessageId','$.resultSessionId')=1 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.sourceSessionId'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.sourceSessionId'))) BETWEEN 1 AND 128 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.resultSessionId'))='STRING' AND CHAR_LENGTH(fork_result_key) BETWEEN 1 AND 128 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.throughMessageId'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.throughMessageId')) AS DECIMAL(20,0)) BETWEEN 1 AND 9223372036854775807)),
    CONSTRAINT ck_workflow_agent_action CHECK (kind<>'AGENT_ACTION' OR (idempotency_scope='AGENT_ACTION' AND CHAR_LENGTH(request_id) BETWEEN 1 AND 36 AND workflow_id=CONCAT('agent-action:',request_id) AND session_id IS NOT NULL AND run_id IS NOT NULL AND resource_type IS NOT NULL AND resource_type='AGENT_ACTION' AND resource_id IS NOT NULL AND expires_at IS NOT NULL AND revision>=1 AND request_sha256 REGEXP '^[a-fA-F0-9]{64}$' AND agent_action_operation IS NOT NULL AND agent_action_operation IN ('ASSIGN_QUALITY_TASK','RETRY_DETECTION','CREATE_DETECTION') AND payload_version=1 AND parent_workflow_id IS NULL AND claim_token IS NULL AND status IN ('PENDING','EXECUTING','NEEDS_REVIEW','SUCCEEDED','REJECTED','CANCELLED','EXPIRED','INVALIDATED') AND ((status IN ('PENDING','EXECUTING','NEEDS_REVIEW') AND finished_at IS NULL) OR (status IN ('SUCCEEDED','REJECTED','CANCELLED','EXPIRED','INVALIDATED') AND (finished_at IS NOT NULL OR (legacy_source IS NOT NULL AND BINARY legacy_source=BINARY 'agent_pending_action' AND legacy_key IS NOT NULL)))))),
    CONSTRAINT ck_workflow_legacy_chat_action CHECK (kind<>'LEGACY_CHAT_ACTION' OR (idempotency_scope='LEGACY_CHAT_ACTION' AND CHAR_LENGTH(request_id)<=64 AND resource_type IS NOT NULL AND resource_type='CHAT_ACTION' AND resource_id IS NOT NULL AND BINARY resource_id=BINARY request_id AND session_id IS NULL AND run_id IS NULL AND parent_workflow_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND payload_version=1 AND result_json IS NULL)),
    CONSTRAINT ck_workflow_model_file_upload CHECK (kind<>'MODEL_FILE_UPLOAD' OR (resource_type IS NOT NULL AND resource_type='DETECTION_MODEL_FILE' AND resource_id IS NOT NULL AND REGEXP_LIKE(resource_id,'^[A-Za-z0-9_-]{1,36}$','c') AND workflow_id=CONCAT('model-file:',resource_id) AND actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND request_id REGEXP '^[A-Za-z0-9_-]{1,128}$' AND payload_version=1 AND JSON_LENGTH(payload_json)=7 AND JSON_CONTAINS_PATH(payload_json,'all','$.storagePath','$.pathSha256','$.contentSha256','$.byteSize','$.modelId','$.legacyCreatedAt','$.legacyUpdatedAt')=1 AND model_file_storage_path IS NOT NULL AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.storagePath')))<=2048 AND model_file_path_sha256 IS NOT NULL AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.pathSha256')))=64 AND model_file_path_sha256 REGEXP '^[a-f0-9]{64}$' AND model_file_path_sha256=SHA2(model_file_storage_path,256) AND ((JSON_TYPE(JSON_EXTRACT(payload_json,'$.contentSha256'))='NULL' AND model_file_content_sha256 IS NULL) OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.contentSha256'))='STRING' AND model_file_content_sha256 IS NOT NULL AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.contentSha256')))=64 AND model_file_content_sha256 REGEXP '^[a-f0-9]{64}$')) AND ((JSON_TYPE(JSON_EXTRACT(payload_json,'$.byteSize'))='NULL' AND model_file_byte_size IS NULL) OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.byteSize'))='INTEGER' AND model_file_byte_size IS NOT NULL AND model_file_byte_size>=0)) AND ((JSON_TYPE(JSON_EXTRACT(payload_json,'$.modelId'))='NULL' AND model_file_model_id IS NULL) OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.modelId'))='INTEGER' AND model_file_model_id IS NOT NULL AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.modelId')) AS DECIMAL(20,0)) BETWEEN -2147483648 AND 2147483647)) AND ((JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyCreatedAt'))='NULL' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyUpdatedAt'))='NULL') OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyCreatedAt'))='STRING' AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyUpdatedAt'))='STRING')) AND resource_revision IS NULL AND requested_tokens IS NULL AND decider_user_id IS NULL AND active_slot IS NULL AND lease_expires_at IS NULL AND result_version IS NULL AND result_sha256 IS NULL AND reserved_bytes IS NULL AND exit_verified IS NULL AND execution_deadline IS NULL AND fence=0 AND attempts=0 AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND result_json IS NULL AND error_code IS NULL AND effective_date IS NULL AND scheduled_for IS NULL AND next_attempt_at IS NULL AND execution_state IS NULL AND status IN ('RESERVED','FILE_READY','REGISTERED','RETAINED') AND ((status='RESERVED' AND model_file_content_sha256 IS NULL AND model_file_byte_size IS NULL AND model_file_model_id IS NULL) OR (status='FILE_READY' AND model_file_content_sha256 IS NOT NULL AND model_file_byte_size IS NOT NULL AND model_file_model_id IS NULL) OR (status IN ('REGISTERED','RETAINED') AND model_file_content_sha256 IS NOT NULL AND model_file_byte_size IS NOT NULL AND model_file_model_id IS NOT NULL)) AND ((status='RETAINED' AND finished_at IS NOT NULL) OR (status<>'RETAINED' AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_quota_resource CHECK (kind NOT IN ('LLM_QUOTA_CHANGE','LLM_QUOTA_APPLICATION') OR (resource_type IS NOT NULL AND resource_type='LLM_MODEL' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id) BETWEEN 1 AND 180 AND actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND payload_version=1)),
    CONSTRAINT ck_workflow_quota_application CHECK ((kind='LLM_QUOTA_APPLICATION' AND requested_tokens IS NOT NULL AND requested_tokens>0 AND status IN ('PENDING','APPROVED','REJECTED','CANCELLED') AND ((status='PENDING' AND decider_user_id IS NULL AND finished_at IS NULL) OR (status IN ('APPROVED','REJECTED') AND decider_user_id IS NOT NULL AND decider_user_id>0 AND finished_at IS NOT NULL) OR (status='CANCELLED' AND decider_user_id IS NOT NULL AND decider_user_id=owner_user_id AND finished_at IS NOT NULL))) OR (kind<>'LLM_QUOTA_APPLICATION' AND requested_tokens IS NULL AND decider_user_id IS NULL)),
    CONSTRAINT ck_workflow_skill_import CHECK (kind<>'SKILL_IMPORT_COMMAND' OR (resource_type IS NOT NULL AND resource_type='SKILL_IMPORT' AND resource_id IS NOT NULL AND resource_revision IS NOT NULL AND resource_revision=1 AND actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND expires_at IS NULL)),
    CONSTRAINT ck_workflow_skill_download CHECK (kind<>'SKILL_DOWNLOAD' OR (resource_type IS NOT NULL AND resource_type='SKILL_DOWNLOAD' AND resource_id IS NOT NULL AND resource_id=workflow_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND CHAR_LENGTH(request_id)<=64 AND status IN ('DOWNLOADING','DOWNLOADED','DRAFT_CREATED','NO_CHANGE','ERROR','NEEDS_REVIEW','PURGING','PURGED','CLEANUP_ERROR') AND ((status='PURGED' AND finished_at IS NOT NULL AND claim_token IS NULL) OR (status<>'PURGED' AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_execution CHECK ((execution_state IS NULL AND reserved_bytes IS NULL AND exit_verified IS NULL AND execution_deadline IS NULL) OR (kind='SKILL_DOWNLOAD' AND execution_state IS NOT NULL AND execution_state IN ('RESERVED','RUNNING','SEALED','RELEASED','NEEDS_REVIEW') AND reserved_bytes IS NOT NULL AND reserved_bytes>=0 AND exit_verified IS NOT NULL AND execution_deadline IS NOT NULL AND ((execution_state IN ('SEALED','RELEASED') AND exit_verified=TRUE AND reserved_bytes=0) OR (execution_state IN ('RESERVED','RUNNING','NEEDS_REVIEW') AND exit_verified=FALSE))) OR (kind='MCP_INSTALLATION' AND execution_state IS NULL AND reserved_bytes IS NOT NULL AND reserved_bytes>=0 AND exit_verified IS NULL AND execution_deadline IS NULL)),
    CONSTRAINT ck_workflow_skill_storage CHECK (kind<>'SKILL_STORAGE_COMMAND' OR (resource_type IS NOT NULL AND resource_type='SKILL_DOWNLOAD' AND resource_id IS NOT NULL AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND CHAR_LENGTH(request_id)<=64 AND expires_at IS NULL AND claim_token IS NULL AND status IN ('STARTED','COMPLETED','ERROR') AND ((status='STARTED' AND finished_at IS NULL) OR (status IN ('COMPLETED','ERROR') AND finished_at IS NOT NULL)))),
    CONSTRAINT ck_workflow_memory_mutation CHECK (kind<>'MEMORY_MUTATION' OR (resource_type IS NOT NULL AND resource_type='MEMORY' AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND CHAR_LENGTH(request_id) BETWEEN 1 AND 64 AND request_sha256 REGEXP '^[a-f0-9]{64}$' AND payload_version=1 AND JSON_LENGTH(payload_json)=1 AND JSON_EXTRACT(payload_json,'$.action') IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.action')) IN ('DELETE','UPDATE','AUTOSAVE','REVIEW_DECISION','LIFECYCLE') AND ((JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.action'))='AUTOSAVE' AND resource_id IS NULL) OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.action'))<>'AUTOSAVE' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id) BETWEEN 1 AND 64)) AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND effective_date IS NULL AND scheduled_for IS NULL AND result_json IS NULL AND status IN ('PENDING','DISPATCHED','SUCCEEDED','REJECTED','UNKNOWN') AND ((status IN ('SUCCEEDED','REJECTED') AND finished_at IS NOT NULL) OR (status IN ('PENDING','DISPATCHED','UNKNOWN') AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_model_config CHECK (kind NOT IN ('MODEL_CONFIG_COMMAND','MODEL_JSON_PROBE') OR (resource_type IS NOT NULL AND resource_type='LLM_CONFIGURATION' AND resource_id IS NOT NULL AND resource_revision IS NOT NULL AND resource_revision>0 AND resource_id=CAST(resource_revision AS CHAR))),
    CONSTRAINT ck_workflow_model_command CHECK (kind<>'MODEL_CONFIG_COMMAND' OR (actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND expires_at IS NULL AND payload_version=1)),
    CONSTRAINT ck_workflow_model_probe CHECK (kind<>'MODEL_JSON_PROBE' OR (model_probe_id IS NOT NULL AND CHAR_LENGTH(model_probe_id) BETWEEN 1 AND 160 AND idempotency_scope=CONCAT('MODEL_CONFIG:',resource_revision) AND payload_version=1 AND status IN ('STARTED','PASSED','FAILED') AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND ((status='STARTED' AND finished_at IS NULL) OR (status IN ('PASSED','FAILED') AND (finished_at IS NOT NULL OR (legacy_source IS NOT NULL AND legacy_source='agent_model_json_probe' AND legacy_key IS NOT NULL)))))),
    CONSTRAINT ck_workflow_report CHECK (kind NOT IN ('REPORT_COMMAND','REPORT_CONFIRMATION','REPORT_DELIVERY','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN') OR (resource_type IS NOT NULL AND resource_type='QUALITY_REPORT' AND resource_id IS NOT NULL AND resource_revision IS NOT NULL AND resource_revision>=0)),
    CONSTRAINT ck_workflow_report_confirmation CHECK (kind<>'REPORT_CONFIRMATION' OR (expires_at IS NOT NULL AND CHAR_LENGTH(request_id)<=64 AND idempotency_scope='REPORT_CONFIRMATION' AND status IN ('PENDING','USED','EXPIRED') AND claim_token IS NULL AND ((status='PENDING' AND finished_at IS NULL) OR (status<>'PENDING' AND finished_at IS NOT NULL)))),
    CONSTRAINT ck_workflow_report_delivery CHECK (kind<>'REPORT_DELIVERY' OR (status IN ('PENDING','RETRY','PROCESSING','DELIVERED','FAILED') AND ((status='PROCESSING' AND claim_token IS NOT NULL) OR (status<>'PROCESSING' AND claim_token IS NULL)) AND ((status='DELIVERED' AND finished_at IS NOT NULL) OR (status<>'DELIVERED' AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_file_delivery CHECK (kind<>'FILE_DELIVERY' OR (resource_type IS NOT NULL AND resource_type='FILE_DELIVERY' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id) BETWEEN 1 AND 160 AND actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope='FILE_DELIVERY' AND request_id=workflow_id AND CHAR_LENGTH(workflow_id)=36 AND payload_version=1 AND file_delivery_scope IS NOT NULL AND file_delivery_scope COLLATE utf8mb4_bin IN ('ENTERPRISE','PRIVATE') AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.scope'))='STRING' AND file_delivery_domain IS NOT NULL AND CHAR_LENGTH(file_delivery_domain) BETWEEN 1 AND 48 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.domain'))='STRING' AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND effective_date IS NULL AND scheduled_for IS NULL AND result_json IS NULL AND status IN ('AUTHORIZED','HEAD_AUTHORIZED','STREAMING','UNKNOWN','SERVER_COMPLETED','HEAD_COMPLETED','INTERRUPTED','REDIRECT_AUTHORIZED') AND ((status IN ('AUTHORIZED','HEAD_AUTHORIZED','STREAMING','UNKNOWN') AND finished_at IS NULL) OR (status IN ('SERVER_COMPLETED','HEAD_COMPLETED','INTERRUPTED','REDIRECT_AUTHORIZED') AND finished_at IS NOT NULL)))),
    CONSTRAINT ck_workflow_digest CHECK (kind<>'DIGEST_RUN' OR status IN ('PENDING','RUNNING','COMPLETED','FAILED','BLOCKED')),
    CONSTRAINT ck_workflow_llm_request CHECK (kind<>'LLM_REQUEST' OR status IN ('OPEN','SETTLING','COMPLETED','NEEDS_REVIEW','CANCELLED')),
    CONSTRAINT ck_workflow_llm_attempt CHECK (kind<>'LLM_PROVIDER_ATTEMPT' OR (parent_workflow_id IS NOT NULL AND status IN ('RESERVED','STARTED','COMPLETED','FAILED','CANCELLED','NEEDS_REVIEW'))),
