 CONSTRAINT ck_workflow_mcp_shape CHECK (kind NOT IN ('MCP_INSTALL_JOB','MCP_EXECUTION','MCP_EXECUTION_COMMAND','MCP_INSTALLATION','MCP_LIFECYCLE_COMMAND','MCP_INSTALL_WORKER','MCP_IMAGE_COMMAND') OR (resource_type=kind AND resource_id IS NOT NULL AND idempotency_scope=CASE WHEN kind IN ('MCP_EXECUTION_COMMAND','MCP_INSTALLATION','MCP_LIFECYCLE_COMMAND','MCP_INSTALL_WORKER','MCP_IMAGE_COMMAND') THEN CONCAT(kind,':OWNER:',owner_user_id) ELSE kind END AND payload_version=1 AND JSON_LENGTH(payload_json)=1 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.schemaVersion'))='INTEGER' AND JSON_EXTRACT(payload_json,'$.schemaVersion')=1 AND claim_token IS NULL AND parent_workflow_id IS NULL AND actor_user_id IS NULL)),
 CONSTRAINT ck_workflow_mcp_execution CHECK (kind<>'MCP_EXECUTION' OR (CHAR_LENGTH(resource_id)=36 AND mcp_installation_id IS NOT NULL AND mcp_runtime_sha256 REGEXP '^[a-f0-9]{64}$' AND mcp_pool_id REGEXP '^[a-f0-9]{32}$' AND mcp_purpose IN ('CALL','PROBE','INSTALL_PROBE') AND mcp_transport IN ('STDIO','STREAMABLE_HTTP') AND mcp_exit_verified IS NOT NULL AND mcp_cleanup_confirmed IS NOT NULL AND (mcp_cleanup_confirmed=FALSE OR mcp_exit_verified=TRUE) AND lease_expires_at IS NOT NULL AND status IN ('OPENING','RUNNING','STOPPING','EXITED','NEEDS_REVIEW','REMOVED'))),
 CONSTRAINT ck_workflow_mcp_installation CHECK (kind<>'MCP_INSTALLATION' OR (CHAR_LENGTH(resource_id)=36 AND mcp_package_version IS NOT NULL AND mcp_transport IN ('STDIO','STREAMABLE_HTTP') AND mcp_writer_exit_verified IS NOT NULL AND mcp_retained_for_rollback IS NOT NULL AND reserved_bytes IS NOT NULL AND reserved_bytes>=0)),
 CONSTRAINT ck_workflow_mcp_job CHECK (kind<>'MCP_INSTALL_JOB' OR (CHAR_LENGTH(resource_id)<=64 AND mcp_owner_username IS NOT NULL AND mcp_runtime_sha256 REGEXP '^[a-f0-9]{64}$' AND (status<>'RUNNING' OR mcp_worker_token IS NOT NULL))),
